// Python's repr()/str() for the value types this program handles: str and int.
// The bidict repr and argparse's "invalid int value: %r" message both funnel
// through here, so the escaping rules have to match CPython's unicode_repr()
// exactly.

import { codePoints, isPrintable } from './unicodedata.mjs';

function hexEscape(cp) {
  if (cp < 0x100) return `\\x${cp.toString(16).padStart(2, '0')}`;
  if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/**
 * repr() of a Python str.
 *
 * Single quotes are preferred; a double-quoted literal is used only when the
 * string contains a single quote and no double quote, which is the one case
 * where switching quotes avoids a backslash.
 */
export function reprStr(text) {
  let hasSingle = false;
  let hasDouble = false;
  for (const cp of codePoints(text)) {
    if (cp === 0x27) hasSingle = true;
    else if (cp === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;

  let out = String.fromCodePoint(quote);
  for (const cp of codePoints(text)) {
    if (cp === quote || cp === 0x5c /* backslash */) {
      out += `\\${String.fromCodePoint(cp)}`;
    } else if (cp === 0x09) {
      out += '\\t';
    } else if (cp === 0x0a) {
      out += '\\n';
    } else if (cp === 0x0d) {
      out += '\\r';
    } else if (cp < 0x20 || cp === 0x7f) {
      out += hexEscape(cp);
    } else if (cp < 0x7f) {
      out += String.fromCodePoint(cp);
    } else if (isPrintable(cp)) {
      out += String.fromCodePoint(cp);
    } else {
      out += hexEscape(cp);
    }
  }
  return out + String.fromCodePoint(quote);
}

/** repr() of a Python int (arbitrary precision, so BigInt). */
export function reprInt(value) {
  return value.toString();
}

/** repr() dispatching on the runtime type, as Python's repr() would. */
export function pyRepr(value) {
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return reprTuple(value);
  throw new TypeError(`no repr() for ${typeof value}`);
}

/** repr() of a Python tuple; arrays stand in for tuples. */
export function reprTuple(items) {
  if (items.length === 0) return '()';
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

/** str() -- identity on str, repr() on everything else this program uses. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

