// A minimal stand-in for Python's exception objects.  What matters for output
// fidelity is the fully-qualified class name, the str() of the exception (used
// as the traceback's final line) and the chain of frames the traceback prints.

import { pyRepr, pyStr, reprTuple } from './repr.mjs';

export class PyException extends Error {
  /**
   * @param {string} qualname  e.g. 'KeyError', 'bidict.ValueDuplicationError'
   * @param {Array} args       the Python exception args tuple
   */
  constructor(qualname, args) {
    super(qualname);
    this.qualname = qualname;
    this.pyArgs = args;
    /** Library-internal frames, outermost first; the caller prepends its own. */
    this.frames = [];
  }

  /** str(exc) -- what follows "ClassName: " on the traceback's last line. */
  displayArgs() {
    if (this.pyArgs.length === 0) return '';
    if (this.pyArgs.length === 1) return pyStr(this.pyArgs[0]);
    return reprTuple(this.pyArgs);
  }

  /** The traceback's final line. */
  formatExceptionOnly() {
    const detail = this.displayArgs();
    return detail === '' ? this.qualname : `${this.qualname}: ${detail}`;
  }

  /** Record a frame as the exception propagates outward. */
  addFrame(frame) {
    this.frames.unshift(frame);
    return this;
  }
}

export class PyKeyError extends PyException {
  constructor(key) {
    super('KeyError', [key]);
    this.key = key;
  }

  // KeyError is the one builtin whose str() is the repr() of its single arg,
  // so that empty or whitespace keys stay visible.
  displayArgs() {
    return this.pyArgs.length === 1 ? pyRepr(this.pyArgs[0]) : super.displayArgs();
  }
}

export class PyValueError extends PyException {
  constructor(message) {
    super('ValueError', [message]);
  }
}

export class PyTypeError extends PyException {
  constructor(message) {
    super('TypeError', [message]);
  }
}

