 * Convert a string to an integer exactly as Python's int() does.
 *
 * @param {string} text
 * @returns {bigint}
 * @throws {PyValueError} for anything int() would reject
 */
export function pyInt(text) {
  const cps = [...codePoints(text)];

  let start = 0;
  let end = cps.length;
