// UTF-8 with Python's "surrogateescape" error handler, on both directions.
//
// The reference program inherits it from the interpreter: bytes in argv that
// are not valid UTF-8 are decoded to lone surrogates U+DC80..U+DCFF (so repr()
// shows them as \udcNN) and are turned back into the original bytes on the way
// out.  Node's own argv decoding is lossy here, which is why raw bytes are
// recovered from /proc/self/cmdline instead.

const SURROGATE_BASE = 0xdc00;

/** Decode UTF-8 bytes, mapping undecodable bytes to U+DC00+byte. */
export function decodeSurrogateEscape(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const byte = bytes[i];
    let length;
    let cp;
    if (byte < 0x80) {
      out += String.fromCharCode(byte);
      i += 1;
      continue;
    } else if (byte >= 0xc2 && byte <= 0xdf) {
      length = 2;
      cp = byte & 0x1f;
    } else if (byte >= 0xe0 && byte <= 0xef) {
      length = 3;
      cp = byte & 0x0f;
    } else if (byte >= 0xf0 && byte <= 0xf4) {
      length = 4;
      cp = byte & 0x07;
    } else {
      out += String.fromCharCode(SURROGATE_BASE + byte);
      i += 1;
      continue;
    }

    let valid = i + length <= bytes.length;
    if (valid) {
      for (let k = 1; k < length; k += 1) {
        const cont = bytes[i + k];
        if ((cont & 0xc0) !== 0x80) {
          valid = false;
          break;
        }
        cp = (cp << 6) | (cont & 0x3f);
      }
    }
    // Reject overlong forms, UTF-16 surrogates and out-of-range code points.
    if (valid) {
      const minimum = length === 2 ? 0x80 : length === 3 ? 0x800 : 0x10000;
      if (cp < minimum || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) valid = false;
    }

    if (!valid) {
      out += String.fromCharCode(SURROGATE_BASE + byte);
      i += 1;
      continue;
    }
    out += String.fromCodePoint(cp);
    i += length;
  }
  return out;
}

/** Encode a string as UTF-8, mapping U+DC80..U+DCFF back to single bytes. */
export function encodeSurrogateEscape(text) {
  const bytes = [];
  for (let i = 0; i < text.length; ) {
    const cp = text.codePointAt(i);
    i += cp > 0xffff ? 2 : 1;

    if (cp >= 0xdc80 && cp <= 0xdcff) {
      bytes.push(cp - SURROGATE_BASE);
    } else if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Uint8Array.from(bytes);
}

