// The pieces of `sys` the program touches: argv, the two standard streams with
// CPython's buffering discipline, and the terminal width argparse formats to.

import { readFileSync, writeSync } from 'node:fs';
import { decodeSurrogateEscape, encodeSurrogateEscape } from './codecs.mjs';
import { pyInt } from './numbers.mjs';

const STDOUT_FD = 1;
const STDERR_FD = 2;
const BLOCK_BUFFER_SIZE = 8192; // io.DEFAULT_BUFFER_SIZE

function writeAll(fd, bytes) {
  const buffer = Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue; // non-blocking tty/pipe: retry
      if (error.code === 'EPIPE') return; // reader went away; drop the rest
      throw error;
    }
  }
}

/**
 * A text stream with the buffering mode CPython picks for it.
 *
 * stdout is line-buffered on a terminal and block-buffered otherwise; stderr is
 * always write-through.  The distinction is observable: when stdout is a pipe
 * and the program dies, the traceback reaches the shared stream *before* the
 * lines already printed.
 */
class TextStream {
  #fd;
  #lineBuffered;
  #pending = [];
  #pendingLength = 0;

  constructor(fd, { lineBuffered, unbuffered = false }) {
    this.#fd = fd;
    this.#lineBuffered = lineBuffered;
    this.unbuffered = unbuffered;
  }

  write(text) {
    if (text === '') return;
    const bytes = encodeSurrogateEscape(text);
    if (this.unbuffered) {
      writeAll(this.#fd, bytes);
      return;
    }
    this.#pending.push(bytes);
    this.#pendingLength += bytes.length;
    if (this.#lineBuffered) {
      if (text.includes('\n')) this.flush();
    } else if (this.#pendingLength >= BLOCK_BUFFER_SIZE) {
      this.flush();
    }
  }

  flush() {
    if (this.#pending.length === 0) return;
    const chunks = this.#pending;
    this.#pending = [];
    this.#pendingLength = 0;
    for (const chunk of chunks) writeAll(this.#fd, chunk);
  }
}

function isTty(fd) {
  const stream = fd === STDOUT_FD ? process.stdout : process.stderr;
  return Boolean(stream && stream.isTTY);
}

export const stdout = new TextStream(STDOUT_FD, { lineBuffered: isTty(STDOUT_FD) });
export const stderr = new TextStream(STDERR_FD, { lineBuffered: true, unbuffered: true });

/** Python's print() for a single object, with the default sep/end. */
export function print(text) {
  stdout.write(`${text}\n`);
}

/**
 * argv[1:] as Python sees it.
 *
 * Node decodes process.argv as UTF-8 with replacement characters, which loses
 * bytes that are not valid UTF-8.  On Linux the original bytes are still
 * available from /proc/self/cmdline, so they are re-decoded with
 * surrogateescape to match the interpreter.
 */
export function argumentVector() {
  const fallback = process.argv.slice(2);
  try {
    const raw = readFileSync('/proc/self/cmdline');
    const fields = [];
    let start = 0;
    for (let i = 0; i < raw.length; i += 1) {
      if (raw[i] === 0) {
        fields.push(raw.subarray(start, i));
        start = i + 1;
      }
    }
    if (start < raw.length) fields.push(raw.subarray(start));
    if (fields.length < fallback.length) return fallback;
    return fields
      .slice(fields.length - fallback.length)
      .map((field) => decodeSurrogateEscape(field));
  } catch {
    return fallback;
  }
}

/**
 * shutil.get_terminal_size().columns -- COLUMNS when it parses to a positive
 * integer, else the width of stdout's terminal, else 80.
 */
export function terminalColumns() {
  const columnsEnv = process.env.COLUMNS;
  if (columnsEnv !== undefined) {
    try {
      const columns = pyInt(columnsEnv);
      if (columns > 0n) return Number(columns);
    } catch {
      // Not an integer: fall through to the terminal query, as Python does.
    }
  }
  if (process.stdout && process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns;
  }
  return 80;
}

/** Flush stdout the way interpreter shutdown does, then exit. */
export function exitProcess(code) {
  stdout.flush();
  stderr.flush();
  process.exit(code);
}

