// An insertion-ordered mapping with Python dict semantics, built on a plain
// null-prototype index plus a slot list.  Keys may be str or int; they are
// type-tagged so that a numeric key never collides with its decimal spelling.
//
// Assigning to an existing key keeps that key's original position; deleting and
// re-inserting moves it to the end -- both of which the reference program's
// output depends on.

/** Distinguish 'x' from 1 in the index namespace. */
function encodeKey(key) {
  if (typeof key === 'bigint') return `i�${key}`;
  if (typeof key === 'string') return `s�${key}`;
  throw new TypeError(`unsupported key type: ${typeof key}`);
}

const MISSING = Symbol('MISSING');

export { MISSING };

export class PyDict {
  #index = Object.create(null);
  #slots = [];
  #size = 0;

  /** @param {Array<[unknown, unknown]>} entries applied in order */
  constructor(entries = []) {
    for (const [key, value] of entries) this.set(key, value);
  }

  get size() {
    return this.#size;
  }

  has(key) {
    return this.#index[encodeKey(key)] !== undefined;
  }

  /** @returns the value, or `fallback` (default MISSING) when absent */
