// The bidirectional mapping itself: a forward mapping plus its inverse, kept in
// step so that both keys and values stay unique.
//
// Duplicate handling follows bidict's default policy, ON_DUP_DEFAULT =
// OnDup(key=DROP_OLD, val=RAISE): re-assigning an existing key silently
// replaces its value, while re-using an existing value raises.

import { MISSING, PyDict } from '../collections/pydict.mjs';
import { PyKeyError } from '../python/exceptions.mjs';
import { pyRepr } from '../python/repr.mjs';
import { FRAMES, KeyAndValueDuplicationError, ValueDuplicationError } from './errors.mjs';

const CLASS_NAME = 'bidict';

/** Read-only view onto a bidict's reversed direction. */
class BidictInverse {
  #owner;

  constructor(owner) {
    this.#owner = owner;
  }

  /** inv[value] -- raises KeyError, carrying bidict's __getitem__ frame. */
  getItem(value) {
    const key = this.#owner.backwardMapping.get(value);
    if (key === MISSING) throw new PyKeyError(value).addFrame(FRAMES.getitem);
    return key;
  }

  has(value) {
    return this.#owner.backwardMapping.has(value);
  }

  get size() {
    return this.#owner.backwardMapping.size;
  }

  *entries() {
    yield* this.#owner.backwardMapping.entries();
  }
}

export class Bidict {
  #forward;
  #backward;
  #inverse;

  /**
   * @param {PyDict|Array<[unknown, unknown]>} [source] the mapping to load,
   *   already de-duplicated by key the way a dict literal would be
   */
  constructor(source) {
    this.#forward = new PyDict();
    this.#backward = new PyDict();
    this.#inverse = new BidictInverse(this);
    if (source !== undefined) {
      const entries = source instanceof PyDict ? [...source.entries()] : source;
      this.#update(entries, [FRAMES.init, FRAMES.update]);
    }
  }

  /** Internal access for the inverse view. */
  get backwardMapping() {
    return this.#backward;
  }

  get inv() {
    return this.#inverse;
  }

  get size() {
    return this.#forward.size;
  }

  has(key) {
    return this.#forward.has(key);
  }

  getItem(key) {
    const value = this.#forward.get(key);
    if (value === MISSING) throw new PyKeyError(key).addFrame(FRAMES.getitem);
    return value;
  }

  /** b[key] = value -- carries the __setitem__/put frames on failure. */
  setItem(key, value) {
    this.#update([[key, value]], [FRAMES.setitem, FRAMES.put, FRAMES.update]);
  }

  copy() {
    const clone = new Bidict();
    clone.#forward = this.#forward.copy();
    clone.#backward = this.#backward.copy();
    return clone;
  }

  *entries() {
    yield* this.#forward.entries();
  }

  /** repr(b) -- 'bidict(' + repr of the equivalent dict + ')'. */
  toString() {
    if (this.#forward.size === 0) return `${CLASS_NAME}()`;
    const items = [];
    for (const [key, value] of this.#forward.entries()) {
      items.push(`${pyRepr(key)}: ${pyRepr(value)}`);
    }
    return `${CLASS_NAME}({${items.join(', ')}})`;
  }

  /**
   * bidict._update: de-duplicate then write, one item at a time.
   *
   * @param {Array<[unknown, unknown]>} entries
   * @param {Array<object>} callerFrames frames to attach ahead of _dedup's
   */
  #update(entries, callerFrames) {
    for (const [key, value] of entries) {
      let plan;
      try {
        plan = this.#dedup(key, value);
      } catch (error) {
        for (const frame of [...callerFrames].reverse()) error.addFrame(frame);
        throw error;
      }
      if (plan !== null) this.#write(key, value, plan.oldKey, plan.oldValue);
    }
  }

  /**
   * bidict._dedup: decide what writing (key, value) means.
   *
   * @returns {{oldKey: unknown, oldValue: unknown}|null} null for a no-op
   */
  #dedup(key, value) {
    const oldValue = this.#forward.get(key);
    const oldKey = this.#backward.get(value);
    const isDupKey = oldValue !== MISSING;
    const isDupValue = oldKey !== MISSING;

    if (isDupKey && isDupValue) {
      // Already present as this exact pair -> nothing to do.
      if (oldKey === key) return null;
      throw new KeyAndValueDuplicationError(key, value).addFrame(FRAMES.dedupKeyAndValue);
    }
    if (isDupKey) {
      // on_dup.key is DROP_OLD: the key keeps its position, the value changes.
      return { oldKey: MISSING, oldValue };
    }
    if (isDupValue) {
      throw new ValueDuplicationError(value).addFrame(FRAMES.dedupValue);
    }
    return { oldKey: MISSING, oldValue: MISSING };
  }

  /** bidict._write: apply the plan to both directions. */
  #write(key, value, oldKey, oldValue) {
    this.#forward.set(key, value);
    this.#backward.set(value, key);
    if (oldValue !== MISSING) this.#backward.delete(oldValue);
    if (oldKey !== MISSING) this.#forward.delete(oldKey);
  }
}

/** `bidict(...)` reads better at the call site than `new Bidict(...)`. */
export function bidict(source) {
  return new Bidict(source);
}

