// The slice of textwrap.wrap() argparse relies on: collapse whitespace, then
// greedily fill lines, splitting a word that cannot fit on its own.

/**
 * @param {string} text
 * @param {number} width
 * @returns {string[]} the wrapped lines, never containing empty strings
 */
export function wrap(text, width) {
  const limit = Math.max(1, width);
  const words = text.split(/\s+/u).filter((word) => word !== '');
  const lines = [];
  let line = '';

  for (const word of words) {
    let remaining = word;
    // A word longer than the whole line is broken across lines.
    while (remaining.length > limit) {
      if (line !== '') {
        lines.push(line);
        line = '';
      }
      lines.push(remaining.slice(0, limit));
      remaining = remaining.slice(limit);
    }
    if (line === '') {
      line = remaining;
    } else if (line.length + 1 + remaining.length <= limit) {
      line += ` ${remaining}`;
    } else {
      lines.push(line);
      line = remaining;
    }
  }
  if (line !== '') lines.push(line);
  return lines;
}

