// argparse's HelpFormatter: usage line, wrapped to the terminal width, and the
// options section.  The wrapping arithmetic is reproduced rather than
// approximated, because a narrow COLUMNS visibly changes both.

import { terminalColumns } from '../python/sys.mjs';
import { wrap } from './textwrap.mjs';

const USAGE_PREFIX = 'usage: ';

// Groups a usage string into wrappable units: bracketed/parenthesised runs stay
// whole, everything else splits on whitespace.
const USAGE_PART = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/gu;

function metavarFor(action) {
  return action.metavar ?? action.dest.toUpperCase();
}

/** _format_action_invocation: how an action is labelled in the options list. */
function invocationOf(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  const metavar = metavarFor(action);
  return action.optionStrings.map((option) => `${option} ${metavar}`).join(', ');
}

/** _format_actions_usage: how an action appears on the usage line. */
function usagePartOf(action) {
  const option = action.optionStrings[0];
  const part = action.nargs === 0 ? option : `${option} ${metavarFor(action)}`;
  return action.required ? part : `[${part}]`;
}

export class HelpFormatter {
  constructor(prog, { indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.width = width ?? terminalColumns() - 2;
    this.maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(this.width - 20, indentIncrement * 2),
    );
    this.actionMaxLength = 0;
  }

  /** The "usage: ..." block, terminated by a blank line. */
  formatUsageBlock(actions) {
    const optionals = actions.filter((action) => action.optionStrings.length > 0);
    const positionals = actions.filter((action) => action.optionStrings.length === 0);
    const actionUsage = optionals
      .concat(positionals)
      .map(usagePartOf)
      .join(' ');
    let usage = [this.prog, actionUsage].filter((piece) => piece !== '').join(' ');

    const textWidth = this.width; // _current_indent is 0 while formatting usage
    if (USAGE_PREFIX.length + usage.length > textWidth) {
      const optParts = [...optionals.map(usagePartOf).join(' ').matchAll(USAGE_PART)].map(
        (match) => match[0],
      );
      const posParts = [...positionals.map(usagePartOf).join(' ').matchAll(USAGE_PART)].map(
        (match) => match[0],
      );

      const getLines = (parts, indent, linePrefix = null) => {
        const lines = [];
        let line = [];
        let lineLength = (linePrefix === null ? indent.length : linePrefix.length) - 1;
        for (const part of parts) {
          if (lineLength + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLength = indent.length - 1;
          }
          line.push(part);
          lineLength += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (linePrefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
        return lines;
      };

      let lines;
      if (USAGE_PREFIX.length + this.prog.length <= 0.75 * textWidth) {
        // Short program name: the first wrapped line starts alongside it.
        const indent = ' '.repeat(USAGE_PREFIX.length + this.prog.length + 1);
        if (optParts.length > 0) {
          lines = getLines([this.prog, ...optParts], indent, USAGE_PREFIX);
          lines.push(...getLines(posParts, indent));
        } else if (posParts.length > 0) {
