    const optionIndices = Object.keys(optionTuples).map(Number);

    const takeAction = (action, argumentStrings, optionString) => {
      if (!seenActions.includes(action)) seenActions.push(action);
      const values = this.#getValues(action, argumentStrings);
      if (action.kind === 'help') {
        this.printHelp();
        this.exit(0);
      }
      namespace[action.dest] = values;
    };

    const consumeOptional = (startIndex) => {
      let [action, optionString, explicitArg] = optionTuples[startIndex];
      const actionTuples = [];
      let stop = startIndex;

      for (;;) {
        // An unknown option: hand the token back as an extra.
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this.#matchArgument(action, 'A');
          if (
            argCount === 0 &&
            !PREFIX_CHARS.includes(optionString[1]) &&
            explicitArg !== ''
          ) {
            // '-hx': a short flag with more single-dash options crammed on.
            const char = optionString[0];
            const nextOptionString = char + explicitArg[0];
            const nextExplicitArg = explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
            if (this.#optionStringActions[nextOptionString] !== undefined) {
              action = this.#optionStringActions[nextOptionString];
              optionString = nextOptionString;
              explicitArg = nextExplicitArg;
              continue;
            }
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
          if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          }
          throw new ArgumentError(
            actionName(action),
            `ignored explicit argument ${reprStr(explicitArg)}`,
          );
        }

        const start = startIndex + 1;
        const argCount = this.#matchArgument(action, pattern.slice(start));
        stop = start + argCount;
        actionTuples.push([action, argStrings.slice(start, stop), optionString]);
        break;
      }

      for (const [act, args, optionStr] of actionTuples) takeAction(act, args, optionStr);
      return stop;
    };

    // With no positional actions declared, anything classified 'A' that no
    // option claims falls through to the extras list.
    let startIndex = 0;
    const maxOptionIndex = optionIndices.length > 0 ? Math.max(...optionIndices) : -1;
    while (startIndex <= maxOptionIndex) {
      const nextOptionIndex = Math.min(...optionIndices.filter((i) => i >= startIndex));
      if (startIndex !== nextOptionIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionIndex));
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(nextOptionIndex);
    }
    extras.push(...argStrings.slice(startIndex));

    const missing = this.#actions
      .filter((action) => action.required && !seenActions.includes(action))
      .map(actionName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * _parse_optional: decide whether a token names an option.
   *
   * @returns {[object|null, string, string|null]|null} null means "a value"
   */
  #parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this.#optionStringActions[argString];
    if (exact !== undefined) return [exact, argString, null];

    if (argString.length === 1) return null; // a bare '-' is a value

    if (argString.includes('=')) {
      const splitAt = argString.indexOf('=');
      const optionString = argString.slice(0, splitAt);
      const explicitArg = argString.slice(splitAt + 1);
      const action = this.#optionStringActions[optionString];
      if (action !== undefined) return [action, optionString, explicitArg];
    }

    const tuples = this.#getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number and no option does, so it is a value.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  /** _get_option_tuples: every option string this token could abbreviate. */
  #getOptionTuples(argString) {
    const result = [];
    const isLong = PREFIX_CHARS.includes(argString[0]) && PREFIX_CHARS.includes(argString[1]);

    if (isLong) {
      let optionPrefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const splitAt = argString.indexOf('=');
        optionPrefix = argString.slice(0, splitAt);
        explicitArg = argString.slice(splitAt + 1);
      }
      for (const optionString of this.#optionStringOrder) {
        if (optionString.startsWith(optionPrefix)) {
          result.push([this.#optionStringActions[optionString], optionString, explicitArg]);
        }
      }
      return result;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const optionString of this.#optionStringOrder) {
      if (optionString === shortPrefix) {
        result.push([this.#optionStringActions[optionString], optionString, shortExplicitArg]);
      } else if (optionString.startsWith(argString)) {
        result.push([this.#optionStringActions[optionString], optionString, null]);
      }
    }
    return result;
  }

  /**
   * _match_argument: how many following tokens this action consumes.
   *
   * For optionals argparse strips '-' out of the nargs pattern, so a '--'
   * marker can never satisfy an option's argument.
   */
  #matchArgument(action, patternSlice) {
    const nargsPattern = action.nargs === 0 ? /^()/u : /^(A)/u;
    const match = nargsPattern.exec(patternSlice);
    if (match === null) {
      throw new ArgumentError(actionName(action), 'expected one argument');
    }
    return match[1].length;
  }

  /** _get_values: convert the collected strings for one action. */
  #getValues(action, argStrings) {
    const strings = argStrings.filter((value, index) => {
      // Only the first '--' is dropped, matching list.remove().
      return !(value === '--' && argStrings.indexOf('--') === index);
    });
    if (action.nargs === null && strings.length === 1) {
      return this.#getValue(action, strings[0]);
    }
    return strings.map((value) => this.#getValue(action, value));
  }

  /** _get_value: run the type callable, translating failures for the user. */
  #getValue(action, argString) {
    try {
      return action.type(argString);
    } catch (error) {
      const name = action.type.typeName ?? 'str';
      throw new ArgumentError(
        actionName(action),
        `invalid ${name} value: ${reprStr(argString)}`,
      );
    }
  }
}

