#!/usr/bin/env node
// Node port of dataset/bidict/test19.py -- copying a bidict, mutating the
// original, and reading the copy's inverse.
//
// Observable behaviour is matched against the reference build, so this file also
// carries the reference's identities: the argparse prog name, the frames its
// tracebacks quote, and the PyInstaller bootloader's failure notice.

import { ArgumentParser, SystemExit, types } from './lib/argparse/index.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { PyDict } from './lib/collections/pydict.mjs';
import { PyException } from './lib/python/exceptions.mjs';
import { argumentVector, exitProcess, print, stderr } from './lib/python/sys.mjs';
import { bootloaderFailureNotice, formatTraceback } from './lib/python/traceback.mjs';

// The reference is a PyInstaller bundle of test19.py; both names surface in
// output, so they are pinned rather than derived from process.argv.
const PROG = 'test19_executable';
const SCRIPT_NAME = 'test19';
const SOURCE_FILE = 'test19.py';

// Frames for the three statements that can raise, with the fine-grained markers
// CPython 3.11+ prints under the failing sub-expression.
const FRAMES = {
  construct: {
    file: SOURCE_FILE,
    line: 12,
    name: '<module>',
    source: 'b1 = bidict({args.k1: args.v1, args.k2: args.v2})',
    markerPad: 5,
    marker: '^'.repeat(44),
  },
  setItem: {
    file: SOURCE_FILE,
    line: 17,
    name: '<module>',
    source: "b1['new'] = 999",
    markerPad: 0,
    marker: '~~^^^^^^^',
  },
  inverseLookup: {
    file: SOURCE_FILE,
    line: 22,
    name: '<module>',
    source: 'result = b2.inv[args.v1]',
    markerPad: 9,
    marker: '~~~~~~^^^^^^^^^',
  },
};

/** Run one statement, tagging any Python-level exception with its frame. */
function atFrame(frame, statement) {
  try {
    return statement();
  } catch (error) {
    if (error instanceof PyException) throw error.addFrame(frame);
    throw error;
  }
}

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--k1'], { type: types.str, required: true });
  parser.addArgument(['--v1'], { type: types.int, required: true });
  parser.addArgument(['--k2'], { type: types.str, required: true });
  parser.addArgument(['--v2'], { type: types.int, required: true });
  return parser;
}

function main() {
  const args = buildParser().parseArgs(argumentVector());

  // The dict literal de-duplicates by key before bidict ever sees it: with
  // k1 == k2 the first key keeps its position and the second value wins.
  const literal = new PyDict([
    [args.k1, args.v1],
    [args.k2, args.v2],
  ]);

  // 复制bidict
  const b1 = atFrame(FRAMES.construct, () => bidict(literal));
  const b2 = b1.copy();
  print(b2.toString());

  // 修改原字典不影响副本
  atFrame(FRAMES.setItem, () => b1.setItem('new', 999n));
  print(b1.toString());
  print(b2.toString());

  // 副本的反转操作
  const result = atFrame(FRAMES.inverseLookup, () => b2.inv.getItem(args.v1));
  print(result);
}

try {
  main();
  exitProcess(0);
} catch (error) {
  if (error instanceof SystemExit) exitProcess(error.code);
  if (error instanceof PyException) {
    // The traceback reaches the shared stream first: stderr is unbuffered while
    // stdout is only flushed at shutdown.
    stderr.write(formatTraceback(error));
    stderr.write(bootloaderFailureNotice(SCRIPT_NAME));
    exitProcess(1);
  }
  throw error;
}

