// linecache.getline() for the entry script.
//
// Tracebacks quote source by *filename*, and the reference's filename is the
// relative path 'test19.py' -- so whether a source line appears at all depends
// on the current working directory.  Run from the directory holding test19.py
// and each frame gains its source text plus a caret marker; run from anywhere
// else and the frames print bare.

import { readFileSync } from 'node:fs';

const cache = Object.create(null);

function linesOf(filename) {
  if (cache[filename] === undefined) {
    try {
      // linecache splits on universal newlines and keeps the line endings; only
      // the split points matter here, since callers strip what they get.
      cache[filename] = readFileSync(filename, 'utf8').split(/\r\n|\r|\n/u);
    } catch {
      cache[filename] = null; // unreadable: getline() yields '' forever
    }
  }
  return cache[filename];
}

/**
 * @param {string} filename resolved relative to the current directory
 * @param {number} lineNumber 1-based
 * @returns {string} the line without its terminator, or '' when unavailable
 */
export function getLine(filename, lineNumber) {
  const lines = linesOf(filename);
  if (lines === null || lineNumber < 1 || lineNumber > lines.length) return '';
  // A trailing newline yields a final empty element that is not a real line.
  if (lineNumber === lines.length && lines[lineNumber - 1] === '') return '';
  return lines[lineNumber - 1];
}

