// Traceback rendering.
//
// The reference build is a PyInstaller bundle: source text is available for the
// entry script (so its frames carry a source line plus a fine-grained
// ~~~^^^ marker) but not for the bundled library modules, whose frames print as
// a bare "File ..., line N, in name".  The bootloader then appends its own
// failure notice, tagged with the process id.

const SOURCE_INDENT = '    ';

/**
 * @typedef {object} Frame
 * @property {string} file
 * @property {number} line
 * @property {string} name
 * @property {string} [source]      source text, without indentation
 * @property {number} [markerPad]   columns to skip before the marker
 * @property {string} [marker]      the ~~~^^^ run
 */

/** Render one frame the way traceback.print_tb() does. */
function formatFrame(frame) {
  let out = `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  if (frame.source !== undefined) {
    out += `${SOURCE_INDENT}${frame.source}\n`;
    if (frame.marker !== undefined) {
      out += `${SOURCE_INDENT}${' '.repeat(frame.markerPad ?? 0)}${frame.marker}\n`;
    }
  }
  return out;
}

