// Traceback rendering.
//
// The reference build is a PyInstaller bundle: the bundled library modules have
// no source on disk, so their frames print as a bare "File ..., line N, in
// name".  The entry script's frames quote source only when its *relative*
// filename resolves against the current directory -- see linecache.mjs.  The
// bootloader then appends its own failure notice, tagged with the process id.

import { getLine } from './linecache.mjs';

const SOURCE_INDENT = '    ';

/**
 * @typedef {object} Frame
 * @property {string} file
 * @property {number} line
 * @property {string} name
 * @property {string} [source]      the genuine source text, stripped
 * @property {number} [markerPad]   columns to skip before the marker
 * @property {string} [marker]      the ~~~^^^ run
 */

/** Render one frame the way traceback.StackSummary does. */
function formatFrame(frame) {
  let out = `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  if (frame.source === undefined) return out;

  const line = getLine(frame.file, frame.line).trim();
  if (line === '') return out; // no source available: frame prints bare
  out += `${SOURCE_INDENT}${line}\n`;

  // The caret anchors are derived from the code object's column offsets applied
  // to this text.  They are reproduced for the genuine source line; a different
  // file sitting at this path gets the source row only.
  if (line === frame.source && frame.marker !== undefined) {
    out += `${SOURCE_INDENT}${' '.repeat(frame.markerPad ?? 0)}${frame.marker}\n`;
  }
  return out;
}

