// Character classification helpers mirroring the CPython predicates that the
// reference program's observable behaviour depends on:
//
//   * str.isprintable()      -- decides whether repr() escapes a character
//   * str.isspace()          -- the set int() strips from both ends
//   * Py_UNICODE_TODECIMAL   -- the digits int() accepts, and their values
//
// Everything is derived at runtime from the Unicode tables the JS engine
// already ships (via RegExp property escapes), so there is no embedded data
// table to drift out of date.

// CPython: "Nonprintable characters are those characters defined in the
// Unicode character database as 'Other' or 'Separator', excepting the ASCII
// space (0x20)."  Categories: Cc Cf Cs Co Cn Zl Zp Zs.
const NONPRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

// str.isspace() is the Unicode White_Space property plus the four ASCII
// information separators (0x1c-0x1f), which CPython classifies as space
// because their bidirectional class is B or S.
const WHITE_SPACE = /\p{White_Space}/u;

// Decimal digits -- category Nd.  Characters that merely have a numeric value
// (superscripts, Roman numerals, ...) are deliberately excluded, matching
// Py_UNICODE_TODECIMAL rather than Py_UNICODE_ISDIGIT/ISNUMERIC.
const DECIMAL_DIGIT = /\p{Nd}/u;

/** Iterate a string by Unicode code point, yielding lone surrogates as-is. */
export function* codePoints(text) {
  for (let i = 0; i < text.length; ) {
    const cp = text.codePointAt(i);
    yield cp;
    i += cp > 0xffff ? 2 : 1;
  }
}

/** True when `cp` is printable in the sense of Python's str.isprintable(). */
export function isPrintable(cp) {
  if (cp === 0x20) return true; // ASCII space is printable by definition
  return !NONPRINTABLE.test(String.fromCodePoint(cp));
}

/** True when `cp` belongs to the whitespace set Python's str.strip() removes. */
export function isSpace(cp) {
  if (cp >= 0x1c && cp <= 0x1f) return true;
  return WHITE_SPACE.test(String.fromCodePoint(cp));
}

function isDecimalDigit(cp) {
  return DECIMAL_DIGIT.test(String.fromCodePoint(cp));
}

// Unicode guarantees that decimal digits come in complete, ascending runs of
// ten.  Consecutive runs (the five mathematical-digit blocks at U+1D7CE, for
// example) concatenate into one longer run that is still a whole number of
// aligned decades, so the value of a digit is its offset from the start of its
// run, modulo ten.
const MAX_RUN_SCAN = 256;

/** Decimal value of `cp` (0-9), or -1 when `cp` is not a decimal digit. */
export function decimalValue(cp) {
  if (!isDecimalDigit(cp)) return -1;
  let runStart = cp;
  for (let scanned = 0; scanned < MAX_RUN_SCAN; scanned += 1) {
    if (runStart === 0 || !isDecimalDigit(runStart - 1)) break;
    runStart -= 1;
  }
  return (cp - runStart) % 10;
}

// int(str) with CPython's base-10 grammar:
//
//   [space*] [+|-] digit (['_'] digit)* [space*]
//
// where "space" is str.isspace() and "digit" is any Unicode decimal digit.
// The result is arbitrary precision, so BigInt -- a 40-digit --v1 has to echo
// back its exact digits.

import { PyValueError } from './exceptions.mjs';
import { codePoints, decimalValue, isSpace } from './unicodedata.mjs';

const UNDERSCORE = 0x5f;
const PLUS = 0x2b;
const MINUS = 0x2d;

/**
 * Convert a string to an integer exactly as Python's int() does.
 *
 * @param {string} text
 * @returns {bigint}
 * @throws {PyValueError} for anything int() would reject
 */
export function pyInt(text) {
  const cps = [...codePoints(text)];

  let start = 0;
  let end = cps.length;
  while (start < end && isSpace(cps[start])) start += 1;
  while (end > start && isSpace(cps[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (cps[start] === PLUS || cps[start] === MINUS)) {
    negative = cps[start] === MINUS;
    start += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (let i = start; i < end; i += 1) {
    const cp = cps[i];
    if (cp === UNDERSCORE) {
      // An underscore is legal only between two digits.
      const nextIsDigit = i + 1 < end && decimalValue(cps[i + 1]) >= 0;
      if (!previousWasDigit || !nextIsDigit) throw invalidLiteral(text);
      previousWasDigit = false;
      continue;
    }
    const value = decimalValue(cp);
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    previousWasDigit = true;
  }

  if (digits === '') throw invalidLiteral(text);
  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

function invalidLiteral(text) {
  // argparse never surfaces this text -- it substitutes its own "invalid int
  // value: %r" message -- but keeping it faithful makes the failure legible.
  return new PyValueError(
    `invalid literal for int() with base 10: ${JSON.stringify(text)}`,
  );
}

