// Parallel differential fuzzer: generate argv vectors, run the reference
// executable and the Node port on each, compare stdout/stderr/exit code.
import { spawn } from 'node:child_process';
import { argv, exit } from 'node:process';

const EXE = '/workspace/dataset/test19_executable';
const JS = '/output/test19.mjs';
const CASES = Number(argv[2] ?? 2000);
const SEED = Number(argv[3] ?? 12345);
const CONCURRENCY = 24;

// Deterministic PRNG so a failing run can be replayed.
let state = SEED >>> 0;
function rnd() {
  state ^= state << 13; state >>>= 0;
  state ^= state >>> 17;
  state ^= state << 5; state >>>= 0;
  return state / 0x100000000;
}
const pick = (list) => list[Math.floor(rnd() * list.length)];
const chance = (p) => rnd() < p;

const KEYS = [
  'a', 'b', 'new', 'x', '999', '', ' ', '  ', 'it\'s', 'say "hi"', 'both \' and "',
  'back\\slash', 'tab\there', 'nl\nhere', 'cr\rhere', '\x00', '\x01\x1f', '\x7f',
  '', ' ', '­', '​', ' ', '　', 'héllo', '中文', '→',
  '😀', '👨‍👩‍👧', '🇯🇵', 'é', '�', '\u{e0001}', '\u{10fffe}', '\u{f0000}',
  '-3', '-3.5', '--k1', '-', '--', 'a=b', 'long'.repeat(30), 'k�k',
  'ﬁ', 'İ', 'ß', '‮', '؜', '᠎', 'a b c', ' pad ', '0', '1', '2',
];
const INTS = [
  '0', '1', '2', '5', '999', '-999', '23', '47', '-0', '+5', '007', '1_000',
  '99999999999999999999999999999999999999999', '-9999999999999999999999999',
  ' 7 ', '\t8\n', '\x0b9\x0c', '\r5', '\x1c5', '5\x1f', ' 5　', ' 5',
  '5', '٧', '७', '７', '𝟕', '²', 'Ⅶ', 'x', '', '1.0', '1e3', '0x10', '0b11',
  'inf', 'nan', 'True', '1 2', '- 3', '--3', '_1', '1_', '1__0', "it's", '3',
];

function makeArgv() {
  const shape = rnd();
  const k1 = pick(KEYS); const k2 = pick(KEYS);
  const v1 = pick(INTS); const v2 = pick(INTS);

  if (shape < 0.55) {
    // Well-formed, randomly ordered, randomly using the '=' form.
    const pairs = [['--k1', k1], ['--v1', v1], ['--k2', k2], ['--v2', v2]];
    for (let i = pairs.length - 1; i > 0; i -= 1) {
      const j = Math.floor(rnd() * (i + 1));
      [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
    }
    const out = [];
    for (const [flag, value] of pairs) {
      if (chance(0.3)) out.push(`${flag}=${value}`);
      else out.push(flag, value);
    }
    return out;
  }
  if (shape < 0.7) {
    // Drop a required option, or duplicate one.
    const pairs = [['--k1', k1], ['--v1', v1], ['--k2', k2], ['--v2', v2]];
    const out = [];
    for (const [flag, value] of pairs) {
      if (chance(0.2)) continue;
      out.push(flag, value);
      if (chance(0.1)) out.push(flag, pick(flag.startsWith('--k') ? KEYS : INTS));
    }
    return out;
  }
  if (shape < 0.85) {
    // Sprinkle in strays, separators and abbreviations.
    const out = ['--k1', k1, '--v1', v1, '--k2', k2, '--v2', v2];
    const strays = ['--', '-', 'pos', '--extra', '-h', '-x', '--k', '--v', '--he',
      '--h', '-hx', '-h=x', '--help=y', '--K1', '--k1x', '-3', '-3.5'];
    const count = 1 + Math.floor(rnd() * 2);
    for (let i = 0; i < count; i += 1) {
      out.splice(Math.floor(rnd() * (out.length + 1)), 0, pick(strays));
    }
    return out;
  }
  // Free-for-all.
  const tokens = ['--k1', '--v1', '--k2', '--v2', '-h', '--help', '--', '-', 'pos',
    k1, v1, k2, v2, '--k', '--v', '--k1=' + k1, '--v1=' + v1];
  const count = 1 + Math.floor(rnd() * 8);
  const out = [];
  for (let i = 0; i < count; i += 1) out.push(pick(tokens));
  return out;
}

function run(command, args) {
  return new Promise((resolve) => {
    const child = spawn(command[0], [...command.slice(1), ...args], {
      env: { ...process.env, COLUMNS: chanceColumns() },
    });
    const out = []; const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('error', () => resolve({ code: -1, out: '', err: 'SPAWN_ERROR' }));
    child.on('close', (code) => resolve({
      code,
      out: Buffer.concat(out).toString('binary'),
      err: Buffer.concat(err).toString('binary'),
    }));
  });
}

