let columnsForCase = '';
function chanceColumns() { return columnsForCase; }

const normalize = (text) => text.replace(/^\[PYI-\d+:ERROR\]/mu, '[PYI-PID:ERROR]');

let pass = 0;
const failures = [];

async function runCase(index) {
  state = (SEED + index * 2654435761) >>> 0;
  rnd(); rnd();
  const args = makeArgv();
  columnsForCase = chance(0.15) ? String(20 + Math.floor(rnd() * 80)) : '';
  const [reference, port] = await Promise.all([run([EXE], args), run(['node', JS], args)]);
  if (
    reference.out === port.out &&
    normalize(reference.err) === normalize(port.err) &&
    reference.code === port.code
  ) {
    pass += 1;
  } else {
    failures.push({ args, columns: columnsForCase, reference, port });
  }
}

const queue = Array.from({ length: CASES }, (unused, i) => i);
await Promise.all(
  Array.from({ length: CONCURRENCY }, async () => {
    for (;;) {
      const index = queue.shift();
      if (index === undefined) return;
      await runCase(index);
    }
  }),
);

console.log(`pass=${pass} fail=${failures.length} of ${CASES}`);
for (const failure of failures.slice(0, 12)) {
  console.log('--- ARGS:', JSON.stringify(failure.args), 'COLUMNS=' + failure.columns);
  console.log('  py rc=%d out=%j err=%j', failure.reference.code, failure.reference.out, failure.reference.err);
  console.log('  js rc=%d out=%j err=%j', failure.port.code, failure.port.out, failure.port.err);
}
exit(failures.length === 0 ? 0 : 1);

