  state = (SEED + index * 2654435761) >>> 0;
  rnd(); rnd();
  const args = makeArgv();
  columnsForCase = chance(0.15) ? String(20 + Math.floor(rnd() * 80)) : '';
  const [reference, port] = await Promise.all([run([EXE], args), run(['node', JS], args)]);
