for (const failure of failures.slice(0, 12)) {
  console.log('--- ARGS:', JSON.stringify(failure.args), 'COLUMNS=' + failure.columns);
  console.log('  py rc=%d out=%j err=%j', failure.reference.code, failure.reference.out, failure.reference.err);
  console.log('  js rc=%d out=%j err=%j', failure.port.code, failure.port.out, failure.port.err);
}
